WITH src AS (SELECT * FROM departments WHERE dept_name = 'Engineering' AND dept_name IN ('Marketing', 'Sales', 'Engineering')), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3372000 THEN 'high' WHEN budget >= 1492000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS total_count, MAX(budget) AS max_budget FROM src GROUP BY CASE WHEN budget >= 3372000 THEN 'high' WHEN budget >= 1492000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, total_count, max_budget FROM budget_bucket_summary ORDER BY budget_bucket ASC;
